js2m1.inicial:
// 1. Crie nome com const
// 2. Crie vida e pocoes com let
// 3. Mostre a primeira linha
// 4. O ataque: tire 35 da vida e mostre a segunda linha
// 5. A poção: some 20 à vida, tire 1 das poções e mostre a terceira linha

testes:
const r = rodar();
saidaIgual(r, [
  "Duda começa com 100 de vida e 3 poções.",
  "Depois do ataque: 65 de vida.",
  "Depois da poção: 85 de vida e 2 poções.",
]);

const declaracao = (nome) => {
  const d = acharNos("VariableDeclaration").find((n) => n.declarations.some((x) => x.id.name === nome));
  return d ? d.kind : null;
};
for (const nome of ["nome", "vida", "pocoes"]) {
  verificar(declaracao(nome) !== null,
    `Não encontrei a variável ${nome}. Crie as três variáveis com estes nomes exatos: nome, vida e pocoes.`);
}
verificar(declaracao("nome") === "const", 'O nome da maga não muda durante a partida: crie com const nome = "Duda";');
verificar(declaracao("vida") === "let", "A vida muda durante a partida: crie com let vida = 100;");
verificar(declaracao("pocoes") === "let", "O número de poções muda durante a partida: crie com let pocoes = 3;");

const r = rodar();
const vida = pegarVar(r, "vida");
const pocoes = pegarVar(r, "pocoes");
verificar(vida === 85,
  `No fim do programa, vida deveria valer 85, mas vale ${mostrar(vida)}. Mude a variável (vida = vida - 35;), em vez de só fazer a conta dentro do console.log.`);
verificar(pocoes === 2,
  `No fim do programa, pocoes deveria valer 2, mas vale ${mostrar(pocoes)}. Tire a poção usada com pocoes = pocoes - 1; (ou pocoes -= 1;).`);
const mudancas = (nome) => [
  ...acharNos("AssignmentExpression").filter((n) => n.left.type === "Identifier" && n.left.name === nome),
  ...acharNos("UpdateExpression").filter((n) => n.argument.type === "Identifier" && n.argument.name === nome),
];
verificar(mudancas("vida").length >= 2,
  "Mude o valor de vida duas vezes: no ataque (vida = vida - 35;) e na poção (vida = vida + 20;).");
const usaOValorAtual = (n) => n.type === "UpdateExpression" || n.operator !== "=" ||
  acharNos("Identifier").some((i) => i.name === n.left.name && i.start >= n.right.start && i.end <= n.right.end);
const direto = [...mudancas("vida"), ...mudancas("pocoes")].find((n) => !usaOValorAtual(n));
verificar(!direto,
  `Na linha ${direto ? direto.linha : ""}, calcule o novo valor a partir do valor atual — vida = vida - 35; ou vida -= 35; — em vez de escrever o resultado.`);

const escritoAMao = (numeros, trechos) => acharNos(["Literal", "TemplateElement"]).find((n) => {
  if (n.type === "Literal" && typeof n.value === "number") return numeros.includes(n.value);
  const texto = n.type === "TemplateElement" ? n.value.cooked : typeof n.value === "string" ? n.value : "";
  return trechos.some((t) => texto.includes(t));
});

const ids = acharNos("Identifier");
const logs = chamadas("console.log");
const semVariavel = logs.find((c) => !ids.some((i) =>
  ["nome", "vida", "pocoes"].includes(i.name) && i.start >= c.start && i.end <= c.end));
verificar(!semVariavel,
  `O console.log da linha ${semVariavel ? semVariavel.linha : ""} não usa as variáveis. Junte o texto e as variáveis com +, como em "Depois do ataque: " + vida + " de vida."`);
const pronto = escritoAMao([65, 85], ["65", "85", "2 poções"]);
verificar(!pronto,
  `Na linha ${pronto ? pronto.linha : ""} há um resultado escrito à mão. Mostre o valor das variáveis, calculado pelo programa.`);

js2m1.solucao:
const nome = "Duda";
let vida = 100;
let pocoes = 3;
console.log(nome + " começa com " + vida + " de vida e " + pocoes + " poções.");

vida -= 35;
console.log("Depois do ataque: " + vida + " de vida.");

vida += 20;
pocoes -= 1;
console.log("Depois da poção: " + vida + " de vida e " + pocoes + " poções.");

