testes:
const r = rodar();
saidaIgual(r, [
  "nome: Léo (string)",
  "nivel: 7 (number)",
  "ouro: 12.5 (number)",
  "temMontaria: true (boolean)",
  "guilda: null (object)",
  "missaoAtual: undefined (undefined)",
]);

const r = rodar();
igual(pegarVar(r, "nome", "string"), "Léo", "A variável nome");
igual(pegarVar(r, "nivel", "number"), 7, "A variável nivel");
igual(pegarVar(r, "ouro", "number"), 12.5, "A variável ouro");
igual(pegarVar(r, "temMontaria", "boolean"), true, "A variável temMontaria");
