}
const pronto = acharNos(["Literal", "TemplateElement"]).find((n) => {
  const texto = n.type === "TemplateElement" ? n.value.cooked : typeof n.value === "string" ? n.value : "";
  return /\((string|number|boolean|object|undefined)\)/.test(texto);
});
verificar(!pronto,
  `Na linha ${pronto ? pronto.linha : ""}, o tipo foi escrito à mão. Deixe o typeof descobrir: " (" + typeof nome + ")"`);

